### 4. 10-Foot Spatial Focus & D-Pad Engine (`app/js/spatial-nav.js`)

This handles remote control navigation (Arrow keys, Enter, Back key 461) with smooth horizontal translation and viewport alignment:

```javascript
/**
 * 10-Foot Spatial Navigation Engine
 */
class SpatialNavigator {
  constructor() {
    this.currentElement = null;
    this.init();
  }

  init() {
    window.addEventListener('keydown', (e) => this.handleKeyDown(e));
  }

  handleKeyDown(e) {
    const key = e.keyCode || e.which;

    switch (key) {
      case 37: // ArrowLeft
        this.move('left');
        e.preventDefault();
        break;
      case 38: // ArrowUp
        this.move('up');
        e.preventDefault();
        break;
      case 39: // ArrowRight
        this.move('right');
        e.preventDefault();
        break;
      case 40: // ArrowDown
        this.move('down');
        e.preventDefault();
        break;
      case 13: // Enter / OK
        if (this.currentElement) this.currentElement.click();
        break;
      case 461: // webOS Remote Back Key
      case 27:  // Escape
        this.handleBack();
        break;
    }
  }

  setFocus(el) {
    if (!el) return;
    if (this.currentElement) {
      this.currentElement.classList.remove('focused');
      this.currentElement.blur();
    }
    this.currentElement = el;
    this.currentElement.classList.add('focused');
    this.currentElement.focus();

    // Notify listeners (for updating Hero Billboard)
    this.currentElement.dispatchEvent(new CustomEvent('tvfocus', { bubbles: true }));

    this.scrollToFocus(el);
  }

  scrollToFocus(el) {
    // Horizontal row scrolling
    const row = el.closest('.shelf-row');
    if (row) {
      const cardWidth = el.offsetWidth + 20;
      const index = Array.from(row.children).indexOf(el);
      const offset = Math.max(0, (index - 1) * cardWidth);
      row.style.transform = `translateX(-${offset}px)`;
    }

    // Vertical shelves container scrolling
    const shelf = el.closest('.shelf');
    const container = document.getElementById('shelves-container');
    if (shelf && container) {
      const shelfIndex = Array.from(container.children).indexOf(shelf);
      container.style.transform = `translateY(-${shelfIndex * 340}px)`;
    }
  }

  move(direction) {
    if (!this.currentElement) {
      const first = document.querySelector('.focusable');
      if (first) this.setFocus(first);
      return;
    }

    const focusables = Array.from(document.querySelectorAll('.focusable:not([style*="display: none"])'));
    const currentRect = this.currentElement.getBoundingClientRect();

    let bestCandidate = null;
    let minDistance = Infinity;

    for (const el of focusables) {
      if (el === this.currentElement) continue;
      const rect = el.getBoundingClientRect();

      const isDirectionMatch = 
        (direction === 'right' && rect.left >= currentRect.right - 10) ||
        (direction === 'left'  && rect.right <= currentRect.left + 10) ||
        (direction === 'down'  && rect.top >= currentRect.bottom - 10) ||
        (direction === 'up'    && rect.bottom <= currentRect.top + 10);

      if (isDirectionMatch) {
        const dx = (rect.left + rect.width / 2) - (currentRect.left + currentRect.width / 2);
        const dy = (rect.top + rect.height / 2) - (currentRect.top + currentRect.height / 2);
        const distance = Math.sqrt(dx * dx + dy * dy);

        if (distance < minDistance) {
          minDistance = distance;
          bestCandidate = el;
        }
      }
    }

    if (bestCandidate) {
      this.setFocus(bestCandidate);
    }
  }

  handleBack() {
    const player = document.getElementById('player-container');
    if (!player.classList.contains('hidden')) {
      const video = document.getElementById('main-video-player');
      video.pause();
      video.src = '';
      player.classList.add('hidden');
      this.setFocus(document.getElementById('hero-btn-play'));
    }
  }
}

window.SpatialNav = new SpatialNavigator();
```

