### 5. Application Coordinator (`app/js/app-tv.js`)

This wires TMDB data, billboard previews, and connects stream playback directly to your **on-device proxy** (`127.0.0.1:8088`):

```javascript
/**
 * CineJoy TV Application Logic
 */
document.addEventListener('DOMContentLoaded', async () => {
  const heroBackdrop = document.getElementById('hero-backdrop');
  const heroTitle = document.getElementById('hero-title');
  const heroRating = document.getElementById('hero-rating');
  const heroYear = document.getElementById('hero-year');
  const heroOverview = document.getElementById('hero-overview');
  const shelvesContainer = document.getElementById('shelves-container');
  const playBtn = document.getElementById('hero-btn-play');

  let currentActiveItem = null;

  // On-device proxy baseUrl (defaults to localhost service)
  const proxyBaseUrl = (window.CINEJOY_CONFIG && window.CINEJOY_CONFIG.proxyBaseUrl) 
    || 'http://127.0.0.1:8088';

  // 1. Fetch TMDB Data
  try {
    const [trending, movies, series] = await Promise.all([
      TMDB.getTrending(),
      TMDB.getPopularMovies(),
      TMDB.getPopularTV()
    ]);

    renderShelf('Trending Now', trending.results);
    renderShelf('Popular Movies', movies.results);
    renderShelf('Binge-Worthy TV Series', series.results);

    // Initial Hero Item
    if (trending.results && trending.results.length > 0) {
      updateHero(trending.results[0]);
    }

    // Set initial focus to first card
    setTimeout(() => {
      const firstCard = document.querySelector('.tv-card');
      if (firstCard) window.SpatialNav.setFocus(firstCard);
    }, 100);

  } catch (err) {
    console.error('Failed to load TMDB catalog:', err);
    heroOverview.innerText = 'Unable to connect to TMDB. Check internet access.';
  }

  // 2. Render Shelf Component
  function renderShelf(title, items) {
    if (!items || !items.length) return;

    const shelf = document.createElement('div');
    shelf.className = 'shelf';

    const h3 = document.createElement('h3');
    h3.className = 'shelf-title';
    h3.innerText = title;
    shelf.appendChild(h3);

    const row = document.createElement('div');
    row.className = 'shelf-row';

    items.forEach((item) => {
      if (!item.poster_path) return;

      const card = document.createElement('div');
      card.className = 'tv-card focusable';
      card.tabIndex = 0;
      card.innerHTML = `<img src="${TMDB_CONFIG.posterBaseUrl}${item.poster_path}" alt="${item.title || item.name}" loading="lazy"/>`;

      // Update hero billboard when this card receives focus
      card.addEventListener('tvfocus', () => updateHero(item));

      // Play on Enter/Click
      card.addEventListener('click', () => startPlayback(item));

      row.appendChild(card);
    });

    shelf.appendChild(row);
    shelvesContainer.appendChild(shelf);
  }

  // 3. Update Hero Billboard on Card Selection
  function updateHero(item) {
    currentActiveItem = item;
    const title = item.title || item.name || 'Unknown';
    const backdrop = item.backdrop_path 
      ? `${TMDB_CONFIG.imageBaseUrl}${item.backdrop_path}` 
      : '';
    const date = item.release_date || item.first_air_date || '';
    const year = date ? date.split('-')[0] : '';
    const rating = item.vote_average ? item.vote_average.toFixed(1) : 'N/A';

    heroTitle.innerText = title;
    heroRating.innerText = `★ ${rating}`;
    heroYear.innerText = year || '2026';
    heroOverview.innerText = item.overview || 'No description available.';

    if (backdrop) {
      heroBackdrop.style.backgroundImage = `url("${backdrop}")`;
    }
  }

  // 4. Play Button Handler
  playBtn.addEventListener('click', () => {
    if (currentActiveItem) startPlayback(currentActiveItem);
  });

  // 5. Connect Playback with On-Device Streaming Engine
  async function startPlayback(item) {
    const isTV = !!item.first_air_date;
    const tmdbId = item.id;
    const title = item.title || item.name;

    const playerContainer = document.getElementById('player-container');
    const playerTitle = document.getElementById('player-title');
    const video = document.getElementById('main-video-player');

    playerTitle.innerText = title;
    playerContainer.classList.remove('hidden');

    try {
      // Stream resolution request to local on-device service (127.0.0.1:8088)
      const resolveUrl = isTV
        ? `${proxyBaseUrl}/resolve?tmdb=${tmdbId}&season=1&episode=1`
        : `${proxyBaseUrl}/resolve?tmdb=${tmdbId}`;

      console.log('Resolving on-device stream from:', resolveUrl);
      const res = await fetch(resolveUrl);
      const data = await res.json();

      if (data && data.url) {
        // Stream URL rewritten through local HLS proxy
        video.src = data.url;
        video.play();
      } else {
        alert('Stream unavailable for this title.');
        playerContainer.classList.add('hidden');
      }
    } catch (e) {
      console.error('Playback initiation error:', e);
      alert('Playback error: ' + e.message);
      playerContainer.classList.add('hidden');
    }
  }
});
```

